Here is the commit message:
rpmsg: glink: Initialize the "intent_req_comp" completion
 variable

The "intent_req_comp" variable is used without initialization which
results in NULL pointer dereference in qcom_glink_request_intent().

we need to initialize the completion variable before using it.

Fixes: 27b9c5b66b23 ("rpmsg: glink: Request for intents when unavailable")
Signed-off-by: Arun Kumar Neelakantam <aneela@codeaurora.org>
Signed-off-by: Bjorn Andersson <bjorn.andersson@linaro.org>

Here is the root cause:
The `intent_req_comp` variable was used in the `qcom_glink_request_intent()` function without being initialized, leading to a potential NULL pointer dereference when the function attempted to access or manipulate this variable. This lack of initialization could cause the program to crash or behave unpredictably when the variable was referenced.

Here is the patch:

 static struct glink_channel *qcom_glink_alloc_channel(struct qcom_glink *glink,
 						      const char *name)
 {
 	struct glink_channel *channel;

 	channel = kzalloc(sizeof(*channel), GFP_KERNEL);
 	if (!channel)
 		return ERR_PTR(-ENOMEM);

 	/* Setup glink internal glink_channel data */
 	spin_lock_init(&channel->recv_lock);
 	spin_lock_init(&channel->intent_lock);

 	channel->glink = glink;
 	channel->name = kstrdup(name, GFP_KERNEL);

 	init_completion(&channel->open_req);
 	init_completion(&channel->open_ack);
+	init_completion(&channel->intent_req_comp);

 	INIT_LIST_HEAD(&channel->done_intents);
 	INIT_WORK(&channel->intent_work, qcom_glink_rx_done_work);

 	idr_init(&channel->liids);
 	idr_init(&channel->riids);
 	kref_init(&channel->refcount);

 	return channel;
 }



